            "progress": {"state": "absent", "matches": ""},
            "backups": {
                "index": {"present": False, "intact": False},
                "progress": {"present": False, "intact": False},
            },
            "disposition": "idle",
            "reason": "idle",
            "checksum": "0" * 64,
        }
        with self.assertRaises(ValueError):
            BranchStore.recovery_diagnostic(
